INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('rhine-karlsruhe-carp', 'Rhine at Karlsruhe', 'Baden-Württemberg', 'DE', 'Freshwater', '["carp", "pike", "wels catfish"]'::jsonb, 'fishing-spot', true, 'The big, powerful Rhine holds specimen carp and huge wels catfish in its groyne fields and slack water. Long sessions from the bank are the norm, with bite alarms and a comfortable bivvy.', '{"lat": 49.0069, "lng": 8.4037}'::jsonb, '{"current": 21, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 75, "humidity": 65, "windSpeed": 8, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy carp or catfish rods", "Boilies and pellets", "Bite alarms", "Large landing mat"], "optional": ["Bivvy for overnight sessions", "Bait boat", "Headlamp"]}'::jsonb, '["Summer nights", "Autumn feeding window", "After a rise in water"]'::jsonb, 'Intermediate', '["A German Fischereischein requires passing a state fishing exam — plan well ahead", "A separate day or season permit (Erlaubnisschein) is needed for the specific stretch", "Night fishing and bait rules vary by state and water"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('mueritz-lakes-pike', 'Müritz Lakes', 'Mecklenburg-Vorpommern', 'DE', 'Freshwater', '["northern pike", "zander", "perch"]'::jsonb, 'duck-spot', true, 'Germany''s largest lake district, a maze of connected lakes and reedy bays in the Mecklenburg plateau. Excellent pike and zander fishing from boat or float tube in quiet, undeveloped surroundings.', '{"lat": 53.42, "lng": 12.68}'::jsonb, '{"current": 22, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 75, "humidity": 65, "windSpeed": 10, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin combo", "Softbaits, jerkbaits and wire traces", "Landing net and unhooking mat", "Polarized sunglasses"], "optional": ["Boat or belly boat hire", "Sounder", "Rain jacket"]}'::jsonb, '["Autumn pike (Sep-Nov)", "Zander at dusk", "Spring after the closed season"]'::jsonb, 'Beginner', '["Mecklenburg-Vorpommern issues a Touristenfischereischein — a 28-day licence with no exam required", "A water-specific permit is still needed on top of the licence", "Zander and pike have closed seasons and minimum sizes"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('ruegen-baltic-sea-trout', 'Rügen Sea Trout', 'Rügen, Baltic Coast', 'DE', 'Saltwater', '["sea trout", "cod", "garfish"]'::jsonb, 'fishing-spot', false, 'Germany''s premier sea trout coastline. Wade the shallow stony shorelines of Rügen and cast for silver fish moving along the drop-offs, best in the cold months when few others are out.', '{"lat": 54.4, "lng": 13.4}'::jsonb, '{"current": 18, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 68, "humidity": 75, "windSpeed": 16, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["9-10ft spin rod or 7-weight fly rod", "Coastal spoons and shrimp flies", "Breathable chest waders", "Polarized sunglasses"], "optional": ["Wading staff", "Line basket for fly", "Thermal layers for winter"]}'::jsonb, '["Spring (Mar-May)", "Autumn (Oct-Dec)", "Onshore wind and broken water"]'::jsonb, 'Intermediate', '["Baltic coastal fishing requires a Fischereischein plus a coastal fishing permit", "Sea trout have a minimum size and a closed season for coloured fish", "Cod bag limits are set annually by EU rules — check before keeping fish"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('isar-bavaria-trout', 'Upper Isar', 'Lenggries, Bavaria', 'DE', 'Fly Fishing', '["brown trout", "grayling", "rainbow trout"]'::jsonb, 'duck-spot', false, 'An alpine river running milky-turquoise out of the Karwendel mountains. Braided gravel channels and clear pools hold wild browns and grayling within an hour of Munich.', '{"lat": 47.68, "lng": 11.57}'::jsonb, '{"current": 12, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 72, "humidity": 60, "windSpeed": 6, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["4-5 weight fly rod", "Nymphs and caddis patterns", "Chest waders with studs", "Polarized sunglasses"], "optional": ["Day permit from the local association", "Wading staff", "Landing net"]}'::jsonb, '["Summer (Jun-Sep)", "Evening rise", "After snowmelt clears"]'::jsonb, 'Intermediate', '["Bavarian Fischereischein required (exam-based) plus a day ticket for the beat", "Fly-only and barbless rules apply on many stretches", "Grayling are protected on some sections — check local rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('bodensee-whitefish', 'Lake Constance', 'Bodensee, Baden-Württemberg', 'DE', 'Freshwater', '["whitefish", "northern pike", "perch"]'::jsonb, 'fishing-spot', false, 'A vast pre-alpine lake shared with Switzerland and Austria, famous for its Felchen whitefish. Deep, clear water also holds big pike in the reed margins and dense shoals of perch.', '{"lat": 47.6, "lng": 9.4}'::jsonb, '{"current": 21, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 75, "humidity": 70, "windSpeed": 8, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Light spin or hegene rig for whitefish", "Small jigs and spoons", "Sounder", "Landing net"], "optional": ["Boat hire", "Downrigger", "Warm layers for early starts"]}'::jsonb, '["Whitefish in summer", "Pike in autumn", "Perch shoals in late summer"]'::jsonb, 'Intermediate', '["Fischereischein plus a Bodensee patent (permit) required", "Rules are coordinated between Germany, Austria and Switzerland — carry the right patent", "Minimum sizes and closed seasons apply to whitefish and pike"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('elbe-hamburg-zander', 'Elbe at Hamburg', 'Hamburg', 'DE', 'Freshwater', '["zander", "wels catfish", "bream"]'::jsonb, 'duck-spot', false, 'A tidal, working river running through the middle of a major port city. Zander hold along the harbour walls and pontoons, and the fishing is often best after dark under the dock lights.', '{"lat": 53.5, "lng": 9.9}'::jsonb, '{"current": 20, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 70, "humidity": 75, "windSpeed": 12, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium-heavy spin rod", "Softbaits and jigheads", "Headlamp", "Fluorocarbon leader"], "optional": ["Boat for the side arms", "Sounder", "Waterproof jacket"]}'::jsonb, '["Night fishing for zander", "Autumn (Sep-Nov)", "Slack tide in the harbour"]'::jsonb, 'Intermediate', '["Hamburg Fischereischein and a Hamburg fishing permit required", "Zander closed season and minimum size apply", "Many port areas are closed to angling — check signage"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('mueggelsee-berlin', 'Müggelsee', 'Berlin', 'DE', 'Freshwater', '["northern pike", "zander", "European eel"]'::jsonb, 'fishing-spot', false, 'Berlin''s largest lake, on the eastern edge of the city and reachable by S-Bahn. Reed beds and drop-offs hold pike and zander, with eel fishing a long-standing local tradition on summer nights.', '{"lat": 52.44, "lng": 13.65}'::jsonb, '{"current": 22, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 77, "humidity": 60, "windSpeed": 8, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium spin combo", "Softbaits and deadbaits", "Wire trace for pike", "Landing net"], "optional": ["Boat or kayak hire", "Bite alarms for eel", "Headlamp"]}'::jsonb, '["Autumn pike", "Summer eel at night", "Early morning zander"]'::jsonb, 'Beginner', '["Berlin Fischereischein plus the Berlin Fischereiabgabemarke required", "A separate lake permit applies on many waters", "Pike and zander have closed seasons — check Berlin fishing rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('danube-bavaria-catfish', 'Danube at Deggendorf', 'Bavaria', 'DE', 'Freshwater', '["wels catfish", "zander", "carp"]'::jsonb, 'duck-spot', false, 'The German Danube runs deep and coloured through Lower Bavaria, holding enormous wels catfish. Fish the confluences and harbour mouths with heavy tackle and be prepared for a long fight.', '{"lat": 48.85, "lng": 12.96}'::jsonb, '{"current": 20, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Humid", "temperature": 77, "humidity": 70, "windSpeed": 6, "windDirection": "SE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy catfish rod (200g+)", "Clonk, large softbaits or live bait rigs", "Heavy braid and leader", "Unhooking mat"], "optional": ["Boat for drifting", "Bite alarms", "Headlamp for night sessions"]}'::jsonb, '["Warm summer nights", "After a flood recedes", "Autumn feeding"]'::jsonb, 'Advanced', '["Bavarian Fischereischein required plus a stretch permit", "Live baitfish is prohibited in Germany", "Catfish have no closed season in most Bavarian waters — verify locally"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('sylt-north-sea', 'Sylt North Sea', 'Sylt, Schleswig-Holstein', 'DE', 'Saltwater', '["European bass", "mackerel", "flounder"]'::jsonb, 'fishing-spot', false, 'Germany''s northernmost island, with a long exposed sand beach on the North Sea side and sheltered Wadden Sea flats behind. Bass have become a genuine target here in recent warm summers.', '{"lat": 54.9, "lng": 8.3}'::jsonb, '{"current": 17, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 66, "humidity": 80, "windSpeed": 18, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Beachcaster or 9ft lure rod", "Grip leads, lugworm, and surface lures", "Waders", "Windproof jacket"], "optional": ["Tide tables", "Head torch", "Rod rest"]}'::jsonb, '["Summer bass (Jul-Sep)", "Mackerel in warm spells", "Flooding tide over the flats"]'::jsonb, 'Intermediate', '["A Fischereischein is required for North Sea coastal angling in Schleswig-Holstein", "Bass have EU minimum size and bag limits — check current rules", "Large parts of the Wadden Sea are a national park with access restrictions"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('wiesent-franconia-trout', 'River Wiesent', 'Franconian Switzerland, Bavaria', 'DE', 'Fly Fishing', '["brown trout", "grayling"]'::jsonb, 'duck-spot', false, 'A limestone stream winding through the cliffs and beer gardens of Franconian Switzerland. Clear, weedy water and a rich insect life make it one of Germany''s finest dry fly rivers.', '{"lat": 49.8, "lng": 11.2}'::jsonb, '{"current": 15, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 73, "humidity": 65, "windSpeed": 5, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["3-4 weight fly rod", "Small dries and nymphs", "Fine tippet", "Waders"], "optional": ["Day ticket from the local association", "Landing net", "Polarized sunglasses"]}'::jsonb, '["Mayfly in late spring", "Summer evening rise", "Grayling in autumn"]'::jsonb, 'Advanced', '["Bavarian Fischereischein required plus a beat day ticket", "Most stretches are fly-only with barbless hooks", "Closed seasons apply to trout and grayling"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('loire-river-catfish', 'River Loire', 'Tours, Centre-Val de Loire', 'FR', 'Freshwater', '["wels catfish", "zander", "northern pike"]'::jsonb, 'fishing-spot', true, 'France''s longest river, wide, shallow and braided with sandbanks below the châteaux. It has become Europe''s best-known wels catfish water, with very large fish taken from the deeper bends.', '{"lat": 47.4, "lng": 0.7}'::jsonb, '{"current": 21, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 79, "humidity": 60, "windSpeed": 8, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy catfish or pike rod", "Large softbaits and deadbaits", "Braided line and heavy leader", "Unhooking mat"], "optional": ["Boat or float tube", "Bite alarms", "Waders for the sandbanks"]}'::jsonb, '["Summer nights for catfish", "Autumn zander", "Spring pike after the closed season"]'::jsonb, 'Intermediate', '["A carte de pêche from the local AAPPMA is required for anyone aged 12 and over", "An interfédérale card covers public water across all mainland départements", "Pike and zander have closed seasons — check the département rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('brittany-sea-bass', 'Brittany Bass Coast', 'Finistère, Brittany', 'FR', 'Saltwater', '["European bass", "pollack", "mackerel"]'::jsonb, 'duck-spot', true, 'Rocky headlands, tidal races and white-water gullies along the Atlantic edge of Brittany. Some of Europe''s best lure fishing for bass, especially where the tide rips past an exposed point.', '{"lat": 48.3, "lng": -4.6}'::jsonb, '{"current": 17, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 66, "humidity": 78, "windSpeed": 16, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["9-10ft lure rod", "Surface lures and soft plastics", "Studded boots", "Buoyancy aid"], "optional": ["Tide tables", "Kayak for offshore reefs", "Waterproof jacket"]}'::jsonb, '["Bass season (May-Oct)", "Two hours either side of low water", "Dawn and dusk"]'::jsonb, 'Intermediate', '["No licence is required for recreational sea fishing in France", "Catch is for personal consumption only — selling it is prohibited", "Bass minimum size and bag limits apply under EU rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('sete-mediterranean-tuna', 'Sète Offshore', 'Sète, Occitanie', 'FR', 'Saltwater', '["bluefin tuna", "dorado", "amberjack"]'::jsonb, 'fishing-spot', false, 'The Gulf of Lion off Sète holds big bluefin tuna through the warm months, often visible smashing bait on the surface. Amberjack and dorado work the offshore structures and fish farms.', '{"lat": 43.35, "lng": 3.6}'::jsonb, '{"current": 24, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 84, "humidity": 65, "windSpeed": 12, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy spin or trolling outfit", "Poppers, stickbaits and trolling lures", "Fighting belt", "Sun protection"], "optional": ["Charter booking", "Fish finder", "Seasickness tablets"]}'::jsonb, '["Bluefin (Jun-Oct)", "Calm days between mistral winds", "Early morning surface activity"]'::jsonb, 'Advanced', '["No licence for recreational sea fishing, but bluefin tuna requires a specific authorisation and tag", "Bluefin is strictly quota-managed — most recreational fishing is catch-and-release", "Check current ICCAT and French rules before targeting tuna"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('dordogne-river-barbel', 'River Dordogne', 'Argentat, Nouvelle-Aquitaine', 'FR', 'Freshwater', '["barbel", "chub", "brown trout"]'::jsonb, 'duck-spot', false, 'Clear, fast water running out of the Massif Central through limestone gorges. Strong barbel and chub in the streamy runs, with trout in the upper reaches below the dams.', '{"lat": 45.09, "lng": 1.94}'::jsonb, '{"current": 18, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 77, "humidity": 60, "windSpeed": 6, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Feeder or light barbel rod", "Pellets and luncheon meat", "Waders", "Landing net"], "optional": ["Day ticket from the AAPPMA", "Rod rest", "Polarized sunglasses"]}'::jsonb, '["Summer barbel", "Evenings in warm weather", "After dam releases settle"]'::jsonb, 'Intermediate', '["Carte de pêche required from the local AAPPMA", "Dam releases can raise water levels fast — check the release schedule", "First-category (salmonid) stretches have a shorter season"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('gave-de-pau-salmon', 'Gave de Pau', 'Pyrénées-Atlantiques', 'FR', 'Fly Fishing', '["Atlantic salmon", "brown trout", "sea trout"]'::jsonb, 'fishing-spot', false, 'One of the last French rivers with a genuine Atlantic salmon run, tumbling out of the Pyrenees towards the Adour. Fast pocket water and deep holding pools below the weirs.', '{"lat": 43.3, "lng": -0.4}'::jsonb, '{"current": 14, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 73, "humidity": 70, "windSpeed": 8, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["8-9 weight fly rod for salmon", "Tube flies and heavy nymphs", "Chest waders with studs", "Wading staff"], "optional": ["Guide hire", "Polarized sunglasses", "Rain jacket"]}'::jsonb, '["Salmon run (Mar-Jul)", "Trout in summer", "After rain lifts the river"]'::jsonb, 'Advanced', '["Carte de pêche plus a migratory fish (migrateur) stamp required for salmon", "Salmon quotas are set annually and the season closes once the quota is reached", "Declare salmon catches as required by the département"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lake-annecy-char', 'Lake Annecy', 'Haute-Savoie', 'FR', 'Freshwater', '["Arctic char", "lake trout", "perch"]'::jsonb, 'duck-spot', false, 'Famously clear alpine water beneath the Savoy pre-Alps. Deep-water Arctic char and lake trout are the prizes, taken by trolling or deep vertical jigging over the drop-offs.', '{"lat": 45.85, "lng": 6.17}'::jsonb, '{"current": 19, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 75, "humidity": 60, "windSpeed": 6, "windDirection": "N"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Light trolling or vertical jigging outfit", "Small spoons and gambe rigs", "Sounder", "Landing net"], "optional": ["Boat hire", "Downrigger", "Warm layer for early starts"]}'::jsonb, '["Char in deep water (Jun-Sep)", "Perch in summer shallows", "Dawn sessions"]'::jsonb, 'Intermediate', '["Carte de pêche required, plus a lake-specific permit on Lake Annecy", "Char and lake trout have minimum sizes and quotas", "Motor and trolling rules are strictly enforced on the lake"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('rhone-river-catfish', 'Rhône near Avignon', 'Provence', 'FR', 'Freshwater', '["wels catfish", "zander", "carp"]'::jsonb, 'fishing-spot', false, 'A big, fast, canalised river running south through Provence. Deep channels and lock cuts hold specimen catfish and zander, with the mistral wind a constant factor.', '{"lat": 43.95, "lng": 4.8}'::jsonb, '{"current": 22, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 84, "humidity": 55, "windSpeed": 18, "windDirection": "N"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy catfish rod", "Large softbaits and clonk", "Braided mainline", "Unhooking mat"], "optional": ["Boat", "Bite alarms", "Sun protection"]}'::jsonb, '["Summer nights", "Calm days between mistral spells", "Autumn zander"]'::jsonb, 'Advanced', '["Carte de pêche required from the local AAPPMA", "Navigation channels are busy — stay clear of commercial traffic", "Zander closed season applies; catfish generally does not"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('normandy-bass-cotentin', 'Cotentin Peninsula', 'Normandy', 'FR', 'Saltwater', '["European bass", "mackerel", "pollack"]'::jsonb, 'duck-spot', false, 'Huge tidal ranges push water across the rocky ledges and sand banks of the Cotentin, concentrating bait and bass. Shore lure fishing and beach casting both produce well here.', '{"lat": 49.6, "lng": -1.6}'::jsonb, '{"current": 17, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 64, "humidity": 80, "windSpeed": 15, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["9-10ft lure or beach rod", "Soft plastics and metal lures", "Waders or studded boots", "Tide tables"], "optional": ["Head torch", "Rod rest", "Waterproof jacket"]}'::jsonb, '["Bass (May-Oct)", "Big spring tides", "Dawn and dusk"]'::jsonb, 'Intermediate', '["No licence required for recreational sea fishing", "Bass minimum size and bag limits apply", "Tides here are among the largest in Europe — check times carefully before fishing rock marks"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('ariege-pyrenees-trout', 'Ariège Mountain Streams', 'Ariège, Occitanie', 'FR', 'Fly Fishing', '["brown trout"]'::jsonb, 'fishing-spot', false, 'Tumbling Pyrenean streams and high mountain lakes holding wild brown trout, many of them small but perfectly marked. Quiet valleys and long walks in for the best water.', '{"lat": 42.8, "lng": 1.6}'::jsonb, '{"current": 13, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 70, "humidity": 60, "windSpeed": 6, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["3-4 weight short fly rod", "Dry flies and small nymphs", "Wading boots", "Light pack"], "optional": ["Hiking gear for high lakes", "Polarized sunglasses", "Map or GPS"]}'::jsonb, '["Summer (Jun-Sep)", "After snowmelt clears", "Warm afternoons at altitude"]'::jsonb, 'Intermediate', '["Carte de pêche required; a réciprocité card covers neighbouring départements", "First-category water — season generally runs March to September", "Some high lakes and reserves are no-kill; check département rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lac-du-der-pike', 'Lac du Der', 'Champagne', 'FR', 'Freshwater', '["northern pike", "zander", "carp"]'::jsonb, 'duck-spot', false, 'One of the largest artificial lakes in Europe, built for flood control on the Marne. Vast shallow flooded margins and standing timber make it a serious big pike and zander venue.', '{"lat": 48.57, "lng": 4.75}'::jsonb, '{"current": 22, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 77, "humidity": 65, "windSpeed": 12, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy spin or float rod", "Large softbaits and deadbaits", "Wire trace", "Large landing net"], "optional": ["Boat hire", "Sounder", "Waterproof clothing"]}'::jsonb, '["Autumn pike (Oct-Dec)", "Spring after the closed season", "Falling water levels in autumn"]'::jsonb, 'Intermediate', '["Carte de pêche plus a Lac du Der specific permit required", "Pike and zander closed seasons apply", "Water levels drop sharply in autumn — check access and launching"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('ebro-mequinenza-catfish', 'Ebro at Mequinenza', 'Aragón', 'ES', 'Freshwater', '["wels catfish", "common carp", "zander"]'::jsonb, 'fishing-spot', true, 'The most famous wels catfish water in Europe, where the Ebro backs up behind the Mequinenza dam. Enormous catfish and hard-fighting carp draw anglers from across the continent.', '{"lat": 41.37, "lng": 0.3}'::jsonb, '{"current": 24, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 93, "humidity": 45, "windSpeed": 8, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy catfish rod", "Pellets, halibut baits and large softbaits", "Braided line 100lb+", "Unhooking mat"], "optional": ["Guided boat session", "Bite alarms", "Sun protection and plenty of water"]}'::jsonb, '["Summer nights", "Spring pre-spawn (Apr-Jun)", "Autumn feeding"]'::jsonb, 'Intermediate', '["An Aragón regional fishing licence is required; licences are issued per autonomous community", "Most guides and lodges will arrange the licence for visiting anglers", "Wels catfish is an introduced species with specific handling and release rules — check regional law"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('strait-of-gibraltar-tuna', 'Strait of Gibraltar', 'Tarifa, Andalusia', 'ES', 'Saltwater', '["bluefin tuna", "albacore", "amberjack"]'::jsonb, 'duck-spot', true, 'Bluefin tuna funnel through the narrow strait between Europe and Africa on their spawning migration. Strong currents and huge fish make this one of the most demanding tuna fisheries anywhere.', '{"lat": 36.0, "lng": -5.6}'::jsonb, '{"current": 21, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Windy", "temperature": 81, "humidity": 65, "windSpeed": 20, "windDirection": "E"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy stand-up outfit (50-130lb)", "Trolling lures and live bait rigs", "Fighting harness", "Sun protection"], "optional": ["Licensed charter", "Seasickness tablets", "Camera"]}'::jsonb, '["Bluefin run (Apr-Jul)", "Between levante wind spells", "Slack current"]'::jsonb, 'Advanced', '["Recreational sea fishing licence from the autonomous community required — usually free", "Since March 2026 sea anglers must report catches through the PescaREC app", "Bluefin tuna is quota-managed and requires a specific authorisation — largely catch-and-release"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('rio-sella-salmon', 'Río Sella', 'Asturias', 'ES', 'Fly Fishing', '["Atlantic salmon", "sea trout", "brown trout"]'::jsonb, 'fishing-spot', false, 'A short, steep river running from the Picos de Europa to the Cantabrian Sea. Spain''s best-known salmon river, where the first fish of the season is auctioned off as the campanu.', '{"lat": 43.4, "lng": -5.1}'::jsonb, '{"current": 15, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Light Rain", "temperature": 72, "humidity": 80, "windSpeed": 8, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["8-9 weight fly rod", "Tube flies and heavy nymphs", "Chest waders with studs", "Rain jacket"], "optional": ["Guide hire", "Wading staff", "Polarized sunglasses"]}'::jsonb, '["Salmon season (May-Jul)", "After rain lifts the water", "Early morning"]'::jsonb, 'Advanced', '["Asturias regional licence plus a salmon permit required; beats are allocated by daily draw", "Salmon quotas are strict and the season closes when the quota is met", "Inland licences in Spain generally require passing an exam in Spanish"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('galicia-rias-bass', 'Galician Rías', 'Rías Baixas, Galicia', 'ES', 'Saltwater', '["European bass", "pollack", "gilthead bream"]'::jsonb, 'duck-spot', false, 'Deep drowned valleys on Spain''s Atlantic corner, cold and rich with bait. Bass and pollack hold on the rocky points and mussel rafts, and the water stays productive year-round.', '{"lat": 42.5, "lng": -8.9}'::jsonb, '{"current": 18, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Overcast", "temperature": 70, "humidity": 80, "windSpeed": 12, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["9-10ft lure rod", "Soft plastics and surface lures", "Studded boots", "Waterproof jacket"], "optional": ["Kayak for the rafts", "Tide tables", "Head torch"]}'::jsonb, '["Bass (May-Nov)", "Dawn around the mussel rafts", "Moving tide"]'::jsonb, 'Intermediate', '["Galicia recreational sea fishing licence required (issued by the region)", "Catch reporting through the PescaREC app applies since March 2026", "Keep clear of commercial mussel rafts and shellfish beds"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('pyrenees-noguera-trout', 'Noguera Pallaresa', 'Lleida, Catalonia', 'ES', 'Fly Fishing', '["brown trout"]'::jsonb, 'fishing-spot', false, 'A clear Pyrenean river running through the Catalan mountains, with wild brown trout in fast pocket water and long glides. Much of the best water is managed as no-kill.', '{"lat": 42.4, "lng": 1.1}'::jsonb, '{"current": 14, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 75, "humidity": 55, "windSpeed": 6, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["4-5 weight fly rod", "Dry flies and Euro-nymph rigs", "Waders", "Polarized sunglasses"], "optional": ["Guide hire", "Wading staff", "Sun hat"]}'::jsonb, '["Spring and early summer (May-Jul)", "Evening rise", "After the snowmelt drops"]'::jsonb, 'Intermediate', '["Catalonia regional fishing licence required", "Many stretches are catch-and-release with barbless single hooks", "Some sections require a separate daily permit booked in advance"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('embalse-orellana-bass', 'Embalse de Orellana', 'Extremadura', 'ES', 'Freshwater', '["largemouth bass", "common carp", "pike"]'::jsonb, 'duck-spot', false, 'A huge Extremaduran reservoir that has become one of Europe''s premier largemouth bass fisheries. Rocky points, flooded olive groves and clear water make for excellent sight fishing.', '{"lat": 39.0, "lng": -5.5}'::jsonb, '{"current": 26, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 97, "humidity": 35, "windSpeed": 10, "windDirection": "SW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Medium baitcast or spin combo", "Soft plastics, crankbaits and topwaters", "Fluorocarbon leader", "Sun protection"], "optional": ["Boat or belly boat", "Sounder", "Wide-brimmed hat"]}'::jsonb, '["Spring spawn (Mar-May)", "Autumn (Sep-Nov)", "Dawn topwater in summer"]'::jsonb, 'Beginner', '["Extremadura regional fishing licence required", "Black bass is a non-native species with specific rules — check current regional law", "Summer heat is extreme — fish early and carry plenty of water"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('balearic-dentex', 'Balearic Islands', 'Mallorca, Balearic Islands', 'ES', 'Saltwater', '["dentex", "amberjack", "European bass"]'::jsonb, 'fishing-spot', false, 'Clear Mediterranean water over rocky reefs and posidonia meadows around Mallorca. Dentex and amberjack are the prize species, taken on spinning tackle over the offshore banks.', '{"lat": 39.6, "lng": 2.9}'::jsonb, '{"current": 25, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 86, "humidity": 65, "windSpeed": 10, "windDirection": "SE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy spin combo (PE3-5)", "Stickbaits and vertical jigs", "Fluorocarbon leader", "Sun protection"], "optional": ["Boat or charter", "Sounder", "Polarized sunglasses"]}'::jsonb, '["Dentex (May-Oct)", "Dawn over the banks", "Calm days"]'::jsonb, 'Advanced', '["Balearic Islands recreational fishing licence required; separate licences exist for shore, boat and spearfishing", "Catch reporting via PescaREC applies since March 2026", "Posidonia meadows are protected — anchoring is restricted"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('canary-islands-marlin', 'Canary Islands Big Game', 'Gran Canaria, Canary Islands', 'ES', 'Saltwater', '["blue marlin", "wahoo", "bigeye tuna"]'::jsonb, 'duck-spot', false, 'Deep water drops away just minutes from the harbour, putting blue marlin within easy reach. The Canaries have produced numerous grander marlin and fish year-round in a mild climate.', '{"lat": 27.75, "lng": -15.6}'::jsonb, '{"current": 23, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 79, "humidity": 65, "windSpeed": 14, "windDirection": "NE"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy trolling outfit (80-130lb)", "Skirted lures and rigged baits", "Fighting chair or harness", "Sun protection"], "optional": ["Charter booking", "Outriggers", "Camera"]}'::jsonb, '["Blue marlin (Jun-Sep)", "Wahoo in autumn", "Calm mornings"]'::jsonb, 'Advanced', '["Canary Islands recreational fishing licence required", "Billfish are generally released; tags and authorisations may apply", "Catch reporting through PescaREC applies to recreational sea anglers"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('rio-duero-barbel', 'Río Duero', 'Castilla y León', 'ES', 'Freshwater', '["barbel", "zander", "common carp"]'::jsonb, 'fishing-spot', false, 'The Duero runs through the wide plains and vineyards of Castilla y León before crossing into Portugal. Strong barbel in the streamy sections and zander in the reservoir stretches.', '{"lat": 41.5, "lng": -4.7}'::jsonb, '{"current": 22, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 88, "humidity": 40, "windSpeed": 10, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Feeder or light spin rod", "Corn, pellets and soft plastics", "Rod rest", "Landing net"], "optional": ["Boat for the reservoirs", "Sun hat", "Cool box"]}'::jsonb, '["Spring and autumn", "Early morning in summer", "After water releases"]'::jsonb, 'Beginner', '["Castilla y León regional fishing licence required", "Inland licences generally require passing a written exam in Spanish", "Zander is non-native and subject to specific rules — check regional law"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('costa-brava-spinning', 'Costa Brava Rock Marks', 'Girona, Catalonia', 'ES', 'Saltwater', '["European bass", "dentex", "bluefish"]'::jsonb, 'duck-spot', false, 'Pine-backed cliffs and rocky coves along the northern Catalan coast, with deep water close in. Spinning from the rocks at first light produces bass, bluefish and the occasional dentex.', '{"lat": 41.9, "lng": 3.2}'::jsonb, '{"current": 25, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 84, "humidity": 65, "windSpeed": 8, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["9ft spin rod", "Stickbaits and metal jigs", "Studded boots", "Buoyancy aid"], "optional": ["Head torch", "Kayak for the coves", "Polarized sunglasses"]}'::jsonb, '["Dawn spinning", "Autumn bluefish", "Calm sea after a blow"]'::jsonb, 'Intermediate', '["Catalonia recreational sea fishing licence required", "Catch reporting via the PescaREC app applies since March 2026", "Marine protected areas along this coast are no-take — check local zoning"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('po-river-catfish', 'River Po', 'Emilia-Romagna', 'IT', 'Freshwater', '["wels catfish", "common carp", "zander"]'::jsonb, 'fishing-spot', true, 'Italy''s greatest river, wide and coloured as it crosses the Padana plain towards the Adriatic. Vast wels catfish live in the deep bends, and the Po delta holds carp and zander in numbers.', '{"lat": 45.0, "lng": 11.8}'::jsonb, '{"current": 25, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Humid", "temperature": 88, "humidity": 75, "windSpeed": 6, "windDirection": "E"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy catfish rod", "Clonk, large softbaits or pellets", "Braided line and heavy leader", "Unhooking mat"], "optional": ["Guided boat trip", "Bite alarms", "Insect repellent"]}'::jsonb, '["Summer nights", "Spring pre-spawn", "After a flood recedes"]'::jsonb, 'Intermediate', '["Freshwater fishing in Italy requires a regional licence — rules differ by region", "Many waters also need a daily or seasonal permit from the local association", "Wels catfish is invasive in Italy; release rules vary — check regional law"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lake-garda-trout', 'Lake Garda', 'Lombardy / Veneto', 'IT', 'Freshwater', '["lake trout", "northern pike", "whitefish"]'::jsonb, 'duck-spot', true, 'Italy''s largest lake, deep and alpine at the northern end and gentler in the south. Trolling for lake trout and the endemic carpione is the local tradition, with big pike in the southern bays.', '{"lat": 45.6, "lng": 10.7}'::jsonb, '{"current": 24, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 84, "humidity": 60, "windSpeed": 12, "windDirection": "N"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Trolling or spin outfit", "Spoons, minnows and deep divers", "Sounder", "Landing net"], "optional": ["Boat hire", "Downrigger", "Sun protection"]}'::jsonb, '["Spring lake trout", "Autumn pike", "Early morning before the wind"]'::jsonb, 'Intermediate', '["A regional licence is required — Lombardy, Veneto and Trentino each issue their own for Garda", "The endemic carpione is fully protected and must be released", "Trolling rules, rod numbers and closed seasons vary by shore"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lake-como-shad', 'Lake Como', 'Lombardy', 'IT', 'Freshwater', '["shad", "lake trout", "perch"]'::jsonb, 'fishing-spot', false, 'Steep mountains drop straight into deep water on this famous Y-shaped lake. Agone shad shoal in huge numbers, and perch fishing from the stone quays is a Lombard institution.', '{"lat": 46.0, "lng": 9.3}'::jsonb, '{"current": 23, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 81, "humidity": 65, "windSpeed": 8, "windDirection": "N"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Light spin or bolognese rod", "Small spoons and live bait rigs", "Landing net", "Polarized sunglasses"], "optional": ["Boat hire", "Sounder", "Sun hat"]}'::jsonb, '["Shad in early summer", "Perch in spring and autumn", "Dawn from the quays"]'::jsonb, 'Beginner', '["Lombardy regional fishing licence required", "A separate provincial permit applies on parts of the lake", "Minimum sizes and closed seasons apply — check provincial regulations"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('sardinia-dentex', 'Sardinian Coast', 'Sardinia', 'IT', 'Saltwater', '["dentex", "amberjack", "European bass"]'::jsonb, 'duck-spot', false, 'Some of the clearest water in the Mediterranean, over rocky reefs and steep drop-offs. Dentex and amberjack are the target species, with excellent spinning and shore jigging from the cliffs.', '{"lat": 40.5, "lng": 9.6}'::jsonb, '{"current": 25, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 86, "humidity": 60, "windSpeed": 12, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy spin combo", "Stickbaits and vertical jigs", "Studded boots for rock marks", "Fluorocarbon leader"], "optional": ["Boat or kayak", "Sounder", "Sun protection"]}'::jsonb, '["Dentex (May-Oct)", "Dawn over the reefs", "Calm days after mistral"]'::jsonb, 'Advanced', '["Recreational sea fishing requires free registration with the MASAF ministry", "Since 2026 anglers must also register and report catches via the RecFishing app", "Marine protected areas around Sardinia have strict no-take zones"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('sicily-bluefin-tuna', 'Egadi Islands', 'Sicily', 'IT', 'Saltwater', '["bluefin tuna", "swordfish", "amberjack"]'::jsonb, 'fishing-spot', false, 'Off western Sicily, where tuna have been fished since antiquity in the tonnara traps. Modern sport boats target bluefin and swordfish in deep water within sight of the Egadi Islands.', '{"lat": 38.0, "lng": 12.3}'::jsonb, '{"current": 26, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 88, "humidity": 65, "windSpeed": 12, "windDirection": "NW"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy stand-up outfit", "Trolling lures and live baits", "Fighting harness", "Sun protection"], "optional": ["Licensed charter", "Outriggers", "Seasickness tablets"]}'::jsonb, '["Bluefin (May-Sep)", "Swordfish at night", "Calm summer days"]'::jsonb, 'Advanced', '["Free MASAF registration plus RecFishing app reporting required", "Bluefin tuna requires a specific authorisation and is quota-managed — mostly catch-and-release", "Swordfish has a seasonal closure under EU rules"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('venice-lagoon-bass', 'Venice Lagoon', 'Veneto', 'IT', 'Saltwater', '["European bass", "gilthead bream", "mullet"]'::jsonb, 'duck-spot', false, 'A vast shallow lagoon of channels, mudflats and fishing valli behind the Venetian islands. Bass and gilthead bream feed on the tide among the bricole posts, often within sight of the city.', '{"lat": 45.4, "lng": 12.35}'::jsonb, '{"current": 25, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Humid", "temperature": 84, "humidity": 75, "windSpeed": 8, "windDirection": "E"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Light spin rod", "Soft plastics and small crankbaits", "Fluorocarbon leader", "Polarized sunglasses"], "optional": ["Small boat or kayak", "Tide tables", "Sun protection"]}'::jsonb, '["Bass on the flooding tide", "Autumn bream", "Dawn among the bricole"]'::jsonb, 'Intermediate', '["Free MASAF registration required for recreational sea fishing, plus RecFishing reporting", "Private fishing valli are closed to the public — respect boundaries", "Navigation and speed limits are strictly enforced in the lagoon"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('noce-river-trentino', 'River Noce', 'Trentino', 'IT', 'Fly Fishing', '["marble trout", "brown trout", "rainbow trout"]'::jsonb, 'fishing-spot', false, 'An alpine river in the Val di Sole, running clear and cold below the Brenta Dolomites. Marble trout and browns hold in the pocket water, in some of the most scenic fishing in Italy.', '{"lat": 46.3, "lng": 11.0}'::jsonb, '{"current": 11, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Clear", "temperature": 73, "humidity": 60, "windSpeed": 6, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["4-5 weight fly rod", "Nymphs and dry flies", "Chest waders with studs", "Wading staff"], "optional": ["Daily permit from the local association", "Polarized sunglasses", "Warm layer"]}'::jsonb, '["Summer (Jun-Sep)", "Evening rise", "When rafting traffic clears"]'::jsonb, 'Intermediate', '["Trentino provincial licence plus a daily beat permit required", "Many stretches are no-kill with barbless hooks", "Marble trout is protected in places — check the local regulation card"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('tiber-river-rome', 'River Tiber', 'Rome, Lazio', 'IT', 'Freshwater', '["wels catfish", "common carp", "chub"]'::jsonb, 'duck-spot', false, 'The Tiber runs green and slow through the middle of Rome, holding surprisingly large wels catfish and carp. Urban fishing with two thousand years of history on the bank behind you.', '{"lat": 41.9, "lng": 12.47}'::jsonb, '{"current": 24, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 90, "humidity": 55, "windSpeed": 6, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy spin or catfish rod", "Large softbaits and pellets", "Braided line", "Unhooking mat"], "optional": ["Rod rest", "Head torch", "Insect repellent"]}'::jsonb, '["Summer evenings", "After autumn rain", "Dawn in the city stretches"]'::jsonb, 'Intermediate', '["Lazio regional fishing licence required", "Some urban stretches are closed to angling — check municipal signage", "Catfish and other invasive species have specific handling rules in Italy"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('argentario-amberjack', 'Monte Argentario', 'Tuscany', 'IT', 'Saltwater', '["amberjack", "dentex", "European bass"]'::jsonb, 'fishing-spot', false, 'A rocky promontory on the Tuscan coast with deep water and offshore seamounts nearby. Amberjack over the wrecks and pinnacles, and bass along the rocky shoreline at first light.', '{"lat": 42.4, "lng": 11.1}'::jsonb, '{"current": 25, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Sunny", "temperature": 86, "humidity": 65, "windSpeed": 10, "windDirection": "W"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Heavy spin or jigging outfit", "Vertical jigs and stickbaits", "Fluorocarbon leader", "Sun protection"], "optional": ["Boat or charter", "Sounder", "Polarized sunglasses"]}'::jsonb, '["Amberjack (May-Oct)", "Dawn over the pinnacles", "Settled summer weather"]'::jsonb, 'Advanced', '["Free MASAF registration and RecFishing catch reporting required", "Minimum sizes and daily limits apply to recreational sea catches", "The Tuscan Archipelago National Park has protected zones nearby"]'::jsonb);
INSERT INTO public.spots (slug, title, location, country, type, species, image_key, featured, description, coordinates, water_temperature, weather, tides, recommended_gear, best_times, difficulty, regulations) VALUES ('lake-maggiore-trout', 'Lake Maggiore', 'Piedmont / Lombardy', 'IT', 'Freshwater', '["lake trout", "whitefish", "northern pike"]'::jsonb, 'duck-spot', false, 'A long, deep pre-alpine lake straddling the Swiss border. Lake trout and whitefish in the deep water, with pike hunting the reedy bays at the southern end.', '{"lat": 45.9, "lng": 8.6}'::jsonb, '{"current": 23, "unit": "°C", "trend": "stable"}'::jsonb, '{"condition": "Partly Cloudy", "temperature": 81, "humidity": 70, "windSpeed": 8, "windDirection": "S"}'::jsonb, '{"nextHigh": "N/A", "nextLow": "N/A", "current": "slack"}'::jsonb, '{"essential": ["Trolling or spin outfit", "Spoons and deep-diving minnows", "Sounder", "Landing net"], "optional": ["Boat hire", "Downrigger", "Rain jacket"]}'::jsonb, '["Lake trout in spring", "Pike in autumn", "Calm early mornings"]'::jsonb, 'Intermediate', '["Piedmont or Lombardy regional licence required depending on the shore", "A Swiss permit is needed for the northern end of the lake", "Closed seasons and minimum sizes vary between provinces"]'::jsonb);
